using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace MeridianStudio.Implementation.AlertPrioritizationWorkflow
{
    public sealed record ComplianceAlert
    {
        public Guid AlertId { get; init; }
        public string TransactionId { get; init; }
        public DateTime Timestamp { get; init; }
        public string Reason { get; init; }
        public decimal Amount { get; init; }
        public string Currency { get; init; }
        public string Counterparty { get; init; }
        public int RiskScore { get; init; }
        public string Status { get; init; }
    }

    public sealed record PrioritizationRule
    {
        public string Name { get; init; }
        public int MinimumRiskScore { get; init; }
        public TimeSpan MaximumAgeHours { get; init; }
        public string RequiredAction { get; init; }
    }

    public sealed record WorkflowConfiguration
    {
        public List<PrioritizationRule> Rules { get; init; } = new List<PrioritizationRule>();
    }

    public sealed class AlertPrioritizationService
    {
        private readonly ILogger<AlertPrioritizationService> _logger;
        private readonly IOptions<WorkflowConfiguration> _options;

        public AlertPrioritizationService(ILogger<AlertPrioritizationService> logger, IOptions<WorkflowConfiguration> options)
        {
            _logger = logger;
            _options = options;
            _logger.LogInformation("AlertPrioritizationService initialized.");
        }

        public async Task<IEnumerable<ComplianceAlert>> PrioritizeAlertsAsync(IEnumerable<ComplianceAlert> alerts, CancellationToken cancellationToken = default)
        {
            _logger.LogInformation("Starting alert prioritization for {AlertCount} alerts.", alerts.Count());
            cancellationToken.ThrowIfCancellationRequested();

            var prioritizedAlerts = new List<ComplianceAlert>();
            var rules = _options.Value.Rules;

            foreach (var alert in alerts)
            {
                cancellationToken.ThrowIfCancellationRequested();
                bool isHighPriority = false;
                string assignedAction = "Review";

                foreach (var rule in rules)
                {
                    if (alert.RiskScore >= rule.MinimumRiskScore && (DateTime.UtcNow - alert.Timestamp) <= rule.MaximumAgeHours)
                    {
                        isHighPriority = true;
                        assignedAction = rule.RequiredAction;
                        _logger.LogDebug("Alert {AlertId} matched rule {RuleName} with action {Action}.", alert.AlertId, rule.Name, assignedAction);
                        break;
                    }
                }

                if (isHighPriority)
                {
                    alert.Status = assignedAction;
                    prioritizedAlerts.Add(alert);
                    _logger.LogDebug("Alert {AlertId} assigned action {Action} and marked for prioritization.", alert.AlertId, assignedAction);
                }
                else
                {
                    alert.Status = "Standard Review";
                    prioritizedAlerts.Add(alert);
                    _logger.LogDebug("Alert {AlertId} assigned standard review.", alert.AlertId);
                }
            }

            _logger.LogInformation("Finished alert prioritization. {PrioritizedCount} alerts processed.", prioritizedAlerts.Count);
            return await Task.FromResult(prioritizedAlerts.OrderByDescending(a => a.RiskScore));
        }
    }
}
